DEV_GRAPH_ROOT="/Users/dm/dev/dev/個人開発/HarnessHub/.worktrees/task-20260728-082322-wt-11/eval-log/dev-graph/live-trial-fixtures/system-spec-lp36-hook-final-r2"
ELICIT_DIR="plugins/system-spec-harness/skills/run-system-spec-elicit"

# Build turns from the brief §2 and §3
# web = confirmed for all 8 categories
# mobile/tablet/desktop-* = excluded for all 8 categories
cat > /tmp/turns.json << 'TURNS'
[
  {
    "qa_id": "QA-DB-WEB",
    "question": "database × web は対象ですか？",
    "answer": "対象。SQLite ファイル 1 個 (todo.db)。テーブルは todos と api_tokens。起動時にスキーマを冪等作成し、マイグレーションは単調増加の SQL 版数で管理する。",
    "ops": [
      {"action": "confirm", "category": "database", "platform": "web", "serves_goals": ["G1", "G3", "G4"]}
    ]
  },
  {
    "qa_id": "QA-AUTH-WEB",
    "question": "auth × web は対象ですか？",
    "answer": "対象。単一利用者向けの bearer token 認証。token は初回起動時にローカル生成し、ハッシュ化して保存する。全 TODO エンドポイントで必須、未認証は 401。",
    "ops": [
      {"action": "confirm", "category": "auth", "platform": "web", "serves_goals": ["G2"]}
    ]
  },
  {
    "qa_id": "QA-UIUX-WEB",
    "question": "ui-ux × web は対象ですか？",
    "answer": "対象。UI は持たない。API の使い勝手として、エラー応答を統一フォーマットにし、OpenAPI 定義を /openapi.json でローカル提供する。",
    "ops": [
      {"action": "confirm", "category": "ui-ux", "platform": "web", "serves_goals": ["G2", "G4"]}
    ]
  },
  {
    "qa_id": "QA-SEC-WEB",
    "question": "security × web は対象ですか？",
    "answer": "対象。localhost バインド固定、外向き通信なし、token はハッシュ保存、入力は schema 検証、SQL は必ずパラメータバインド。",
    "ops": [
      {"action": "confirm", "category": "security", "platform": "web", "serves_goals": ["G1", "G2"]}
    ]
  },
  {
    "qa_id": "QA-INFRA-WEB",
    "question": "infrastructure × web は対象ですか？",
    "answer": "対象。常駐ミドルウェアなし。1 コマンド起動、データはファイル 1 個。バックアップはそのファイルのコピー。",
    "ops": [
      {"action": "confirm", "category": "infrastructure", "platform": "web", "serves_goals": ["G1", "G4"]}
    ]
  }
]
TURNS

python3 "$ELICIT_DIR/scripts/apply-spec-transition.py" chunk \
  --state "$DEV_GRAPH_ROOT/system-spec/spec-state.json" \
  --turns /tmp/turns.json \
  --max-loops 5 \
  --out "$DEV_GRAPH_ROOT/system-spec/spec-state.json" 2>&1

DEV_GRAPH_ROOT="/Users/dm/dev/dev/個人開発/HarnessHub/.worktrees/task-20260728-082322-wt-11/eval-log/dev-graph/live-trial-fixtures/system-spec-lp36-hook-final-r2"
ELICIT_DIR="plugins/system-spec-harness/skills/run-system-spec-elicit"

# Chunk 2: remaining 3 web cells
cat > /tmp/turns2.json << 'TURNS'
[
  {
    "qa_id": "QA-BACK-WEB",
    "question": "backend × web は対象ですか？",
    "answer": "対象。Python の ASGI/WSGI ベース REST API。/todos の CRUD と完了操作、/health。層は router / service / repository の 3 層。",
    "ops": [
      {"action": "confirm", "category": "backend", "platform": "web", "serves_goals": ["G2", "G3"]}
    ]
  },
  {
    "qa_id": "QA-FRONT-WEB",
    "question": "frontend × web は対象ですか？",
    "answer": "対象。専用フロントエンドを実装しない。動作確認は OpenAPI 定義と HTTP クライアント (curl 等) で行う。",
    "ops": [
      {"action": "confirm", "category": "frontend", "platform": "web", "serves_goals": ["G4"]}
    ]
  },
  {
    "qa_id": "QA-MAINT-WEB",
    "question": "maintenance-ops × web は対象ですか？",
    "answer": "対象。構造化ログを標準出力へ、/health で稼働確認、バックアップ/復旧手順を README 化。監視の外部送信は行わない。",
    "ops": [
      {"action": "confirm", "category": "maintenance-ops", "platform": "web", "serves_goals": ["G3", "G4"]}
    ]
  }
]
TURNS

python3 "$ELICIT_DIR/scripts/apply-spec-transition.py" chunk \
  --state "$DEV_GRAPH_ROOT/system-spec/spec-state.json" \
  --turns /tmp/turns2.json \
  --max-loops 5 \
  --out "$DEV_GRAPH_ROOT/system-spec/spec-state.json" 2>&1

