file.content:
        "linked_at"
      ],
      "properties": {
        "repo": {
          "type": "string",
          "pattern": "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$"
        },
        "issue_number": {
          "type": "integer",
          "minimum": 1
        },
        "sync_direction": {
          "const": "beads_to_github_push_only"
        },
        "linked_at": {
          "type": "string",
          "format": "date-time"
        }
      },
      "description": "bd github sync --push-onlyが作ったviewer用Issue identity。C12はIssue mutationせずPR marker/Projects auto-add照合だけに使う"
    }
  },
  "required": [
    "bd_issue_id",
    "linked_at",
    "sync_state"
  ]
},
"github_publication": {
  "type": "object",
  "additionalProperties": false,
  "required": [
    "mode",
    "project_aliases",
    "labels",
    "milestone"
  ],
  "properties": {
    "mode": {
      "type": "string",
      "enum": [
        "local_only",
        "issue",
        "issue_and_projects"
      ]
    },
    "project_aliases": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "labels": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "milestone": {
      "type": [
        "string",
        "null"
      ]
    }
  },
  "description": "task specification確定後の外部publication intent。project_aliases空かつmode=issue_and_projectsの場合はrepo configのdefault/auto-add targetを使う。draft/unconfirmed/evaluation非pass/readiness非completeではmodeに関わらず外部write禁止。"
},
"github_project_linkages": {
  "type": "array",
  "uniqueItems": true,
  "description": "1つのtask/issueを複数GitHub Projects v2へ関連付ける永続linkage。field valueのupdatedAtは競合hintに使い、削除/欠落/renameも扱うcanonical 3-way baseはfield_snapshotとする。Beads mirrorはviewer-onlyで本linkageのcustom-field同期対象外。",
  "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
      "project_alias",
      "owner_type",
      "owner_login",
      "project_number",
      "project_id",
      "item_id",
      "sync_state",
      "field_snapshot",
      "linked_at",
      "last_synced_at"
    ],
    "properties": {
      "project_alias": {
        "type": "string",
        "minLength": 1
      },
      "owner_type": {
        "type": "string",
        "enum": [
          "organization",
